Here is a C++ function that takes a queue of integers as input, deletes all the elements except for the last element, and reverses the order of the remaining elements in the queue:

```cpp
#include <iostream>
#include <queue>
using namespace std;

void deleteAndReverse(queue<int>& q) {
    int lastElement = q.back(); // Store the last element

    while (q.size() > 1) {
        q.pop(); // Delete elements except for the last one
    }

    q.push(lastElement); // Push the last element back to the queue

    // Reverse the order of the remaining elements
    queue<int> reversedQueue;
    while (!q.empty()) {
        reversedQueue.push(q.front());
        q.pop();
    }

    q = reversedQueue; // Assign the reversed queue back to the original queue
}

int main() {
    queue<int> q;
    q.push(1);
    q.push(2);
    q.push(3);
    q.push(4);
    q.push(5);

    deleteAndReverse(q);

    // Output the remaining elements in the queue
    while (!q.empty()) {
        cout << q.front() << " ";
        q.pop();
    }

    return 0;
}
```

